import { useRef, type ReactNode, type PointerEvent } from "react";
import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";

export function TiltCard({ children }: { children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const rect = useRef<DOMRect | null>(null);
  const x = useMotionValue(0.5);
  const y = useMotionValue(0.5);
  const spring = { stiffness: 200, damping: 20 };
  const rotateX = useSpring(useTransform(y, [0, 1], [10, -10]), spring);
  const rotateY = useSpring(useTransform(x, [0, 1], [-10, 10]), spring);

  function onEnter(e: PointerEvent) {
    if (e.pointerType === "touch") return;
    rect.current = ref.current!.getBoundingClientRect(); // measure once, not on every move
  }
  function onMove(e: PointerEvent) {
    const r = rect.current;
    if (!r) return;
    x.set((e.clientX - r.left) / r.width);
    y.set((e.clientY - r.top) / r.height);
  }
  function onLeave() {
    rect.current = null;
    x.set(0.5);
    y.set(0.5);
  }

  return (
    <div style={{ perspective: 900 }}>
      <motion.div
        ref={ref}
        onPointerEnter={onEnter}
        onPointerMove={onMove}
        onPointerLeave={onLeave}
        style={{ rotateX, rotateY, transformStyle: "preserve-3d" }}
        className="rounded-2xl border border-slate-200 bg-white p-6 shadow-xl dark:border-slate-800 dark:bg-slate-900"
      >
        {children}
      </motion.div>
    </div>
  );
}

type Card = { id: string; columnId: string; title: string };

function moveCard(cards: Card[], id: string, to: string, index: number): Card[] {
  const card = cards.find((c) => c.id === id);
  if (!card) return cards;
  const rest = cards.filter((c) => c.id !== id);
  const col = rest.filter((c) => c.columnId === to);
  const moved = { ...card, columnId: to };
  const at =
    index >= col.length
      ? col.length ? rest.indexOf(col[col.length - 1]) + 1 : rest.length
      : rest.indexOf(col[index]);
  return [...rest.slice(0, at), moved, ...rest.slice(at)];
}

